function hover(e,t){e.setAttribute("src",t)}function unhover(e,t){e.setAttribute("src",t)}$(window).on("beforeunload",function(){$(window).scrollTop(0)});$(document).ready(function(){if(window.location.hash){window.location=""}$("body").scrollspy({target:"#sidebar"});$(".back-to-top a,a[href*=#]:not([href=#])").click(function(){if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")||location.hostname==this.hostname){if(this.parentNode.className==="back-to-top"){this.hash="#intro"}var e=$(this.hash);e=e.length?e:$("[name="+this.hash.slice(1)+"]");if(e.length){var t=-50;if(this.hash!=="#intro"){t=e.offset().top}$("html,body").animate({scrollTop:t},1e3);return false}}});if(document.documentElement.clientWidth<992){$(".social-image img").each(function(){this.onmouseover=null});$(".social-image img").each(function(){this.onmouseout=null});$("#facebook-logo").attr("src","./img/facebook.jpg");$("#indiegogo-logo").attr("src","./img/indiegogo.jpg")}setTimeout(function(){$("body").scrollspy("refresh")},10)})
